  const questions = rows.map(({ topic, level, item }, index) => {
    const [prompt, correct, wrongA, wrongB, explanation, detail, reasonA, reasonB, misconception, sourceOverride] = item;
    const [category, subcategory, illustration, source] = groups[topic];
    const correctAnswer = [1, 0, 2][index % 3];
    const options = [wrongA, wrongB];
    options.splice(correctAnswer, 0, correct);
    const optionExplanations = options.map(option => option === correct
      ? `Juist: ${explanation}`
      : option === wrongA ? reasonA : reasonB);
    const image = illustration ? `images/question-${String(index + 221).padStart(3, '0')}.svg` : null;
    const imageAlt = illustration
      ? `Schematische illustratie bij ${subcategory.toLocaleLowerCase('nl')}. De vraag beschrijft: ${prompt}` : null;
    const tags = [topic, level === 'hard' ? 'instinker' : 'toepassen'];
    if (level === 'hard') tags.push('gevaarherkenning', 'veelgemaakte-denkfout');
    if (/\bNIET\b|niet toegestaan|verboden|onjuist/i.test(prompt)) tags.push('negatief-geformuleerd');
    return {
      id: index + 221, category, subcategory, question: prompt,
      options, correctAnswer, explanation, optionExplanations,
      difficulty: level === 'easy' ? 'makkelijk' : level === 'medium' ? 'gemiddeld' : 'moeilijk',
      type: level === 'hard' ? 'instinker' : 'meerkeuze', source: sourceOverride || source,
      image, imageAlt, focusDetail: detail, misconception, tags,
      illustrationKind: image ? illustration : null
    };
  });
  window.THEORY_QUESTIONS_EXTRA = questions;
